  wealthThresholdSignIn: { en: "Sign in to save private alert thresholds for this crop.", hi: "इस फसल के निजी अलर्ट सीमा सहेजने के लिए साइन इन करें।", mr: "या पिकाच्या खाजगी सूचना मर्यादा जतन करण्यासाठी साइन इन करा." },
  wealthThresholdInvalid: { en: "Enter a positive price and percentage values from 0 to 100.", hi: "सकारात्मक मूल्य और 0 से 100 के बीच प्रतिशत दर्ज करें।", mr: "धनात्मक किंमत आणि 0 ते 100 मधील टक्केवारी भरा." },
