  weatherSearchDescription: { en: "If automatic location does not work, search for your village, district, or city and choose a result.", hi: "अगर स्वचालित स्थान काम न करे, तो अपना गाँव, ज़िला या शहर खोजकर परिणाम चुनें।", mr: "स्वयंचलित स्थान काम करत नसल्यास, तुमचे गाव, जिल्हा किंवा शहर शोधून परिणाम निवडा." },
  weatherSearchInput: { en: "Village, district, or city", hi: "गाँव, ज़िला या शहर", mr: "गाव, जिल्हा किंवा शहर" },
  weatherSearchPlaceholder: { en: "For example: Bhatodi or Beed", hi: "उदाहरण: भाटोडी या बीड", mr: "उदा.: भाटोडी किंवा बीड" },
  weatherSearchHint: { en: "Type at least 2 letters to search India.", hi: "भारत में खोजने के लिए कम से कम 2 अक्षर लिखें।", mr: "भारतात शोधण्यासाठी किमान 2 अक्षरे टाइप करा." },
