  weatherSearchNoResults: { en: "No Indian forecast locations matched that search. Try a nearby district or city.", hi: "इस खोज से भारत में कोई पूर्वानुमान स्थान नहीं मिला। पास का ज़िला या शहर खोजें।", mr: "या शोधाशी जुळणारे भारतीय हवामान अंदाजाचे ठिकाण सापडले नाही. जवळचा जिल्हा किंवा शहर शोधा." },
  weatherSearchUnavailable: { en: "Location search is temporarily unavailable. You can still enter your farm location below.", hi: "स्थान खोज अस्थायी रूप से उपलब्ध नहीं है। आप नीचे अपनी खेत की जगह दर्ज कर सकते हैं।", mr: "स्थान शोध सध्या उपलब्ध नाही. तुम्ही खाली तुमच्या शेताचे ठिकाण भरू शकता." },
