  helpTitle: { en: "Help centre", hi: "सहायता केंद्र", mr: "मदत केंद्र" },
  helpDescription: { en: "Use a clear, close photo in natural light. Include one leaf or plant at a time, and keep important field decisions with your local agronomist.", hi: "प्राकृतिक रोशनी में पास से साफ़ तस्वीर लें। एक बार में एक पत्ती या पौधा दिखाएँ और महत्वपूर्ण खेत निर्णय स्थानीय कृषि विशेषज्ञ के साथ लें।", mr: "नैसर्गिक प्रकाशात जवळून स्पष्ट फोटो घ्या. एका वेळी एक पान किंवा झाड दाखवा आणि महत्त्वाचे शेत निर्णय स्थानिक कृषी तज्ज्ञासोबत घ्या." },
  locationTitle: { en: "Farm location", hi: "खेत का स्थान", mr: "शेताचे स्थान" },
  locationDescription: { en: "Choose the village shown in your farm brief. This updates the local context displayed in CropWise.", hi: "अपने खेत विवरण में दिखाया गया गाँव चुनें। इससे CropWise में दिखने वाला स्थानीय संदर्भ अपडेट होगा।", mr: "तुमच्या शेत तपशिलात दाखवलेले गाव निवडा. यामुळे CropWise मधील स्थानिक संदर्भ अद्यतनित होईल." },
  searchTitle: { en: "Search your field notes", hi: "अपने खेत नोट खोजें", mr: "तुमच्या शेत नोंदी शोधा" },
  searchDescription: { en: "Search is ready for crop names, soil notes, scan results, and mandi prices once your farm records are connected.", hi: "खेत रिकॉर्ड जुड़ने के बाद खोज फसल नाम, मिट्टी नोट, स्कैन परिणाम और मंडी मूल्य के लिए तैयार है।", mr: "तुमच्या शेत नोंदी जोडल्यावर शोध पीक नावे, माती नोंदी, स्कॅन निकाल आणि मंडी भावांसाठी तयार आहे." },
  notificationsTitle: { en: "Farm notifications", hi: "खेत सूचनाएँ", mr: "शेत सूचना" },
  notificationsDescription: { en: "Your next alert is the field-preparation reminder due tomorrow. CropWise will keep action reminders together here.", hi: "आपका अगला अलर्ट कल की खेत-तैयारी याद दिलाना है। CropWise सभी काम की यादें यहाँ रखेगा।", mr: "तुमची पुढील सूचना उद्याच्या शेत-तयारीची आठवण आहे. CropWise सर्व कृती आठवणी येथे एकत्र ठेवेल." },
  dailyBriefTitle: { en: "Today’s field brief", hi: "आज का खेत विवरण", mr: "आजचा शेत आढावा" },
  dailyBriefDescription: { en: "Rain is expected late Thursday. Keep field preparation flexible and avoid irrigation until the surface soil starts to dry.", hi: "गुरुवार देर से बारिश की संभावना है। खेत तैयारी लचीली रखें और सतह की मिट्टी सूखने तक सिंचाई न करें।", mr: "गुरुवारी उशिरा पावसाची शक्यता आहे. शेताची तयारी लवचिक ठेवा आणि वरची माती सुकू लागेपर्यंत सिंचन टाळा." },
  cropCalendarTitle: { en: "Crop calendar", hi: "फसल कैलेंडर", mr: "पीक दिनदर्शिका" },
  cropCalendarDescription: { en: "Your field-preparation step is due tomorrow. Seed selection follows once preparation is complete.", hi: "खेत तैयारी का काम कल तक है। तैयारी पूरी होने के बाद बीज चयन करें।", mr: "तुमचे शेत-तयारीचे काम उद्या देय आहे. तयारी पूर्ण झाल्यावर बियाणे निवडा." },
