  recommendationDescription: { en: "The shortlist currently weighs Kharif timing, soil fit, rainfall, and market signal. Crop cards can be selected to review each option.", hi: "यह सूची अभी खरीफ समय, मिट्टी अनुकूलता, वर्षा और बाज़ार संकेतों को देखती है। हर विकल्प देखने के लिए फसल कार्ड चुनें।", mr: "ही यादी सध्या खरीप वेळ, मातीची अनुकूलता, पाऊस आणि बाजार संकेत विचारात घेते. प्रत्येक पर्याय पाहण्यासाठी पीक कार्ड निवडा." },
  soilReportTitle: { en: "Soil profile", hi: "मिट्टी प्रोफ़ाइल", mr: "माती प्रोफाइल" },
  soilReportDescription: { en: "The current field note shows loamy black soil, pH 6.3, and organic carbon at 0.74%. These are strong starting signals for the shortlist.", hi: "वर्तमान खेत नोट में दोमट काली मिट्टी, pH 6.3 और जैविक कार्बन 0.74% दिखता है। ये सूची के लिए मजबूत शुरुआती संकेत हैं।", mr: "सध्याच्या शेत नोंदीत चिकण काळी माती, pH 6.3 आणि सेंद्रिय कार्बन 0.74% दिसते. ही यादीसाठी मजबूत सुरुवातीची चिन्हे आहेत." },
  expertTitle: { en: "Ask a Krishi expert", hi: "कृषि विशेषज्ञ से पूछें", mr: "कृषी तज्ज्ञाला विचारा" },
  expertDescription: { en: "Use your scan result as a concise field note when discussing a crop concern with a local expert.", hi: "स्थानीय विशेषज्ञ से फसल की चिंता पर बात करते समय स्कैन परिणाम को संक्षिप्त खेत नोट की तरह उपयोग करें।", mr: "स्थानिक तज्ज्ञासोबत पिकाच्या समस्येवर चर्चा करताना स्कॅन निकाल संक्षिप्त शेत नोंद म्हणून वापरा." },
  openCropHealth: { en: "Open crop health check", hi: "फसल स्वास्थ्य जाँच खोलें", mr: "पीक आरोग्य तपासणी उघडा" },
